-- Targeted front lat pulldown review; retain manual edits and immutable histories.
BEGIN;
SELECT id FROM "Exercise" WHERE id='00000000-0000-4000-8000-000000000119' FOR UPDATE;
DO $$ BEGIN
 IF EXISTS (SELECT 1 FROM "Exercise" WHERE id='00000000-0000-4000-8000-000000000119' AND ("ownerUserId" IS NOT NULL OR name <> 'Puxada Frontal na Máquina')) THEN RAISE EXCEPTION 'Pulldown identity changed; review manually'; END IF;
 IF EXISTS (SELECT 1 FROM "Exercise" e WHERE e.id='00000000-0000-4000-8000-000000000119' AND e."anatomyReview" IS NULL AND (EXISTS (SELECT 1 FROM "ExerciseMuscle" m WHERE m."exerciseId"=e.id AND NOT ((m."muscleGroup"='BACK' AND m.role='PRIMARY') OR (m."muscleGroup" IN ('BICEPS','FOREARMS') AND m.role='SECONDARY'))) OR (SELECT count(*) FROM "ExerciseMuscle" m WHERE m."exerciseId"=e.id)<>3)) THEN RAISE EXCEPTION 'Pulldown classification changed; review manually'; END IF;
END $$;
INSERT INTO "ExerciseMuscle" (id,"exerciseId","muscleGroup",role,"createdAt") SELECT gen_random_uuid()::text,e.id,g::"MuscleGroup",'SECONDARY'::"MuscleRole",CURRENT_TIMESTAMP FROM "Exercise" e CROSS JOIN (VALUES ('SHOULDERS'),('CORE')) groups(g) WHERE e.id='00000000-0000-4000-8000-000000000119' AND e."ownerUserId" IS NULL AND e."anatomyReview" IS NULL ON CONFLICT ("exerciseId","muscleGroup") DO NOTHING;
UPDATE "Exercise" e SET "anatomyReview"='{"version":"2026-11-12.1","reviewedAt":"2026-11-12T19:00:00.000Z","variant":"Puxada frontal sentada na polia alta, barra reta e pegada pronada a cerca de 1,5 vez a largura dos ombros; tronco estável levemente reclinado.","aliases":["puxada frontal na máquina","puxada frontal na polia alta com pegada pronada"],"participants":[{"id":"LATISSIMUS_DORSI","label":"Latíssimo do dorso","muscleGroup":"BACK","role":"PRIMARY","aliases":["dorsal","grande dorsal","latissimus dorsi"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["BUONSENSO_2025","OPENSTAX_UPPER"]},{"id":"TERES_MAJOR","label":"Redondo maior","muscleGroup":"BACK","role":"PRIMARY","aliases":["teres major"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["OPENSTAX_UPPER"]},{"id":"TRAPEZIUS","label":"Trapézio","muscleGroup":"BACK","role":"SECONDARY","aliases":["trapézio médio","trapézio inferior","trapezius"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["BUONSENSO_2025","OPENSTAX_UPPER"]},{"id":"RHOMBOIDS","label":"Romboides","muscleGroup":"BACK","role":"SECONDARY","aliases":["romboide maior","romboide menor"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["OPENSTAX_UPPER"]},{"id":"DELTOID_POSTERIOR","label":"Deltoide posterior","muscleGroup":"SHOULDERS","role":"SECONDARY","aliases":["ombro posterior"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["BUONSENSO_2025","OPENSTAX_UPPER"]},{"id":"INFRASPINATUS","label":"Infraespinal","muscleGroup":"SHOULDERS","role":"SECONDARY","aliases":["infraespinhoso","manguito rotador"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["BUONSENSO_2025","OPENSTAX_UPPER"]},{"id":"BICEPS_BRACHII","label":"Bíceps braquial","muscleGroup":"BICEPS","role":"SECONDARY","aliases":["bíceps"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["BUONSENSO_2025","OPENSTAX_UPPER"]},{"id":"BRACHIALIS","label":"Braquial","muscleGroup":"BICEPS","role":"SECONDARY","aliases":["braquial anterior"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["OPENSTAX_UPPER"]},{"id":"BRACHIORADIALIS","label":"Braquiorradial","muscleGroup":"FOREARMS","role":"SECONDARY","aliases":["braquiorradialis"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["OPENSTAX_UPPER"]},{"id":"FLEXOR_DIGITORUM_SUPERFICIALIS","label":"Flexor superficial dos dedos","muscleGroup":"FOREARMS","role":"SECONDARY","aliases":["pegada"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["OPENSTAX_UPPER"]},{"id":"FLEXOR_DIGITORUM_PROFUNDUS","label":"Flexor profundo dos dedos","muscleGroup":"FOREARMS","role":"SECONDARY","aliases":["pegada"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["OPENSTAX_UPPER"]},{"id":"FLEXOR_CARPI_ULNARIS","label":"Flexor ulnar do carpo","muscleGroup":"FOREARMS","role":"SECONDARY","aliases":["punho"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["OPENSTAX_UPPER"]},{"id":"EXTENSOR_CARPI_RADIALIS_BREVIS","label":"Extensor radial curto do carpo","muscleGroup":"FOREARMS","role":"SECONDARY","aliases":["punho"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["OPENSTAX_UPPER"]},{"id":"ERECTOR_SPINAE","label":"Eretores da coluna","muscleGroup":"BACK","role":"SECONDARY","aliases":["eretor da espinha","estabilizadores do tronco"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["OPENSTAX_UPPER"]},{"id":"RECTUS_ABDOMINIS","label":"Reto abdominal","muscleGroup":"CORE","role":"SECONDARY","aliases":["abdômen","abdominais"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["OPENSTAX_UPPER"]},{"id":"EXTERNAL_OBLIQUE","label":"Oblíquo externo","muscleGroup":"CORE","role":"SECONDARY","aliases":["oblíquos"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["OPENSTAX_UPPER"]}],"sources":[{"id":"BUONSENSO_2025","title":"Buonsenso et al. — Electromyographic Analysis of Back Muscle Activation During Lat Pulldown Exercise (2025)","url":"https://doi.org/10.3390/jfmk10030345","limitation":"40 homens com pelo menos cinco anos de treino; cinco repetições a 70% de 1RM, sete pegadas/inclinações e cadência 2 s/2 s. EMG de dorsal, trapézio médio/inferior, deltoide posterior, bíceps e infraespinal. Sem superioridade geral entre pegadas; maior sinal de deltoide posterior com 30° em comparações específicas. Não mede hipertrofia nem determina ângulos ideais."},{"id":"OPENSTAX_UPPER","title":"OpenStax Anatomy and Physiology 2e — Muscles of the Pectoral Girdle and Upper Limbs","url":"https://openstax.org/books/anatomy-and-physiology-2e/pages/11-5-muscles-of-the-pectoral-girdle-and-upper-limbs","limitation":"Anatomia funcional: adução/extensão do ombro, flexão do cotovelo, controle escapular e pegada. Papéis não medidos no estudo e estabilização do tronco são inferências anatômicas/editoriais, sem quantificação nesta variação."}],"notes":"Dorsal e redondo maior são os motores destacados; flexores do cotovelo, controle escapular, manguito, pegada e estabilizadores do tronco são coenvolvidos. Grupo BACK permanece principal, embora eretores/trapézio/romboides tenham papel secundário específico. Sem isolamento do dorsal, ranking de EMG ou ênfase regional demonstrada. Inclinação fixa de cerca de 7°, barra à frente do rosto e pegada de 1,5 vez os ombros são escolhas ilustrativas confortáveis do rig, não ótimos universais. Não extrapolar os resultados de 30° para esta postura. Sem subdividir dorsal em regiões não comprovadas. Cores representam categorias ilustrativas.","instructions":{"description":"Puxada frontal na polia alta, sentada, com barra e pegada pronada moderadamente aberta.","setup":"Ajuste o assento e o apoio sobre as coxas. Apoie os pés no chão e segure a barra um pouco além dos ombros, com as palmas voltadas para a frente. Mantenha o tronco firme e levemente inclinado para trás.","execution":"Conduza os cotovelos para baixo e puxe a barra à frente do rosto até o alto do peito, sem embalar o tronco. Faça uma pausa breve e deixe a barra subir com controle, alongando os braços sem perder o apoio.","tips":"Mantenha os punhos alinhados aos antebraços e evite puxar atrás da nuca. Use uma amplitude confortável, sem forçar o contato com o peito. Dorsal, redondo maior e músculos auxiliares participam juntos; cores ilustram participação, sem medir EMG ou intensidade real."}}'::jsonb,"updatedAt"=CURRENT_TIMESTAMP WHERE e.id='00000000-0000-4000-8000-000000000119' AND e."ownerUserId" IS NULL AND e."anatomyReview" IS NULL;
COMMIT;
